// Lishaq Solutions — Navigation
(function () {
  function closeMenu() {
    const nav = document.querySelector(".nav-links");
    const button = document.querySelector(".menu-toggle");

    if (!nav || !button) return;

    nav.classList.remove("open");
    button.classList.remove("active");
    button.setAttribute("aria-expanded", "false");
  }

  function openMenu() {
    const nav = document.querySelector(".nav-links");
    const button = document.querySelector(".menu-toggle");

    if (!nav || !button) return;

    nav.classList.add("open");
    button.classList.add("active");
    button.setAttribute("aria-expanded", "true");
  }

  function toggleMenu() {
    const nav = document.querySelector(".nav-links");

    if (!nav) return;

    if (nav.classList.contains("open")) {
      closeMenu();
    } else {
      openMenu();
    }
  }

  // Normalize URL paths
  function normalizePath(path) {
    if (!path) return "/";
    
    // Remove query string/hash
    path = path.split("?")[0].split("#")[0];

    // Ensure leading slash
    if (!path.startsWith("/")) {
      path = "/" + path;
    }

    // Root stays /
    if (path === "/") return "/";

    // Remove trailing slash
    return path.replace(/\/+$/, "");
  }

  // Highlight current page
  function setActiveNavLink() {
    const navLinks = document.querySelectorAll(".nav-links a");
    
    if (!navLinks.length) return;

    const currentPath = normalizePath(window.location.pathname);

    let bestMatch = null;
    let bestLength = 0;

    navLinks.forEach((link) => {
      // Remove old active state
      link.classList.remove("active");
      link.removeAttribute("aria-current");

      // Ignore CTA button for active-page matching
      if (link.closest(".nav-cta")) return;

      const linkPath = normalizePath(
        new URL(link.href, window.location.origin).pathname
      );

      // Exact match
      if (currentPath === linkPath) {
        bestMatch = link;
        bestLength = linkPath.length;
        return;
      }

      // Match child pages:
      // /services/web-development/ → /services/
      if (
        linkPath !== "/" &&
        currentPath.startsWith(linkPath + "/") &&
        linkPath.length > bestLength
      ) {
        bestMatch = link;
        bestLength = linkPath.length;
      }
    });

    if (bestMatch) {
      bestMatch.classList.add("active");
      bestMatch.setAttribute("aria-current", "page");
    }
  }

  // Handle clicks
  document.addEventListener("click", function (event) {
    const toggleButton = event.target.closest(".menu-toggle");

    // Hamburger button
    if (toggleButton) {
      event.stopPropagation();
      toggleMenu();
      return;
    }

    // Navigation link
    const navLink = event.target.closest(".nav-links a");

    if (navLink) {
      // Close mobile menu immediately
      closeMenu();
      return;
    }

    // Click outside mobile navigation
    const nav = document.querySelector(".nav-links");
    const button = document.querySelector(".menu-toggle");

    if (
      nav &&
      nav.classList.contains("open") &&
      !nav.contains(event.target) &&
      !button?.contains(event.target)
    ) {
      closeMenu();
    }
  });

  // Close menu with Escape
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") {
      closeMenu();
    }
  });

  // Close mobile menu when returning to desktop
  window.addEventListener("resize", function () {
    if (window.innerWidth > 900) {
      closeMenu();
    }
  });

  // Header is loaded dynamically, so initialize after components load
  document.addEventListener("componentsLoaded", function () {
    setActiveNavLink();
  });

  // Also run on normal DOM load
  document.addEventListener("DOMContentLoaded", function () {
    setActiveNavLink();
  });



  // Scroll reveal
  const io = new IntersectionObserver(
    (entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) {
          e.target.classList.add("in");
          io.unobserve(e.target);
        }
      });
    },
    { threshold: 0.12 },
  );

  document.querySelectorAll(".reveal").forEach((el) => io.observe(el));
  
})();
